import{_ as r,o,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2019-12-09 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-12-09 :: Ceph Orchestration Meeting","date":"2019-12-09T00:00:00.000Z","updated":"2019-12-10T00:00:00.000Z","tags":["Ceph","Distributed Storage","Orchestration","System Unit","Containerization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-09_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-12-09_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-12-09_-_-_Ceph_Orchestration_Meeting.md"};function s(a,t,l,h,g,_){return o(),e("div",null,[...t[0]||(t[0]=[n('<p>在2019年12月9日的Ceph Orchestration会议中，与会人员讨论了多个与Ceph分布式存储系统相关的关键议题。以下是对会议主要内容的总结：</p><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><ul><li><strong>SSH Orchestrator监控</strong>：Paul开始创建SSH Orchestrator的监控功能，会议参与者对此表示赞赏并计划进行审查。</li><li><strong>多驱动组命名</strong>：讨论了支持多个驱动组的情况，并建议为每个驱动组命名以便更好地理解和描述其用途。</li><li><strong>LVM与EVS兼容性</strong>：Sebastian提到LVM与EVS不兼容的问题，建议考虑不使用LVM。</li><li><strong>系统单元和容器化</strong>：讨论了系统单元和容器化的问题，特别是容器关闭时的清理工作。</li><li><strong>Python 3迁移</strong>：计划在接下来的一周内进行Python 3的迁移。</li><li><strong>OMAP转换问题</strong>：在升级到Octopus版本时，发现了OMAP使用统计信息的不同消息，讨论了如何处理这一问题。</li></ul><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ul><li><strong>SSH Orchestrator的监控和命名规范</strong>：如何有效地监控SSH Orchestrator，并为多个驱动组提供命名规范。</li><li><strong>LVM与EVS的兼容性问题</strong>：讨论了LVM与EVS之间的兼容性问题，并探讨了可能的解决方案。</li><li><strong>系统单元和容器化的清理工作</strong>：如何确保在容器关闭时进行适当的清理工作，避免遗留问题。</li><li><strong>Python 3迁移和OMAP转换</strong>：计划进行Python 3的迁移，并处理OMAP转换过程中出现的问题。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li><strong>驱动组命名</strong>：决定为每个驱动组命名以便更好地理解和描述其用途。</li><li><strong>LVM的使用</strong>：考虑不使用LVM，以避免与EVS的兼容性问题。</li><li><strong>系统单元和容器化的清理工作</strong>：决定需要一个包装器来处理容器关闭时的清理工作。</li><li><strong>Python 3迁移</strong>：计划在接下来的一周内进行Python 3的迁移。</li><li><strong>OMAP转换问题</strong>：决定不自动转换OMAP，而是通过文档告知用户，并可能在未来进行自动化处理。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li><strong>审查SSH Orchestrator监控功能</strong>：对Paul创建的监控功能进行审查。</li><li><strong>处理LVM问题</strong>：进一步讨论和决定如何处理LVM与EVS的兼容性问题。</li><li><strong>系统单元和容器化的清理工作</strong>：开发一个包装器来处理容器关闭时的清理工作。</li><li><strong>Python 3迁移</strong>：进行Python 3的迁移，并确保相关代码的兼容性。</li><li><strong>OMAP转换问题</strong>：更新文档，告知用户OMAP转换的问题，并考虑未来的自动化解决方案。</li></ul><p>会议讨论了多个重要议题，并做出了相应的决定和后续行动计划。所有参与者将继续推进这些任务，以确保项目的顺利进行。</p>',10)])])}const d=r(i,[["render",s]]);export{p as __pageData,d as default};
